@@ -0,0 +1,126 @@
+/*
+    KWin - the KDE window manager
+    This file is part of the KDE project.
+
+    SPDX-FileCopyrightText: 2014 Thomas Lübking <thomas.luebking@gmail.com>
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+#include "minimizeall.h"
+#include "virtualdesktops.h"
+#include "window.h"
+#include "workspace.h"
+
+#include <algorithm>
+
+namespace KWin
+{
+
+static bool isRelevant(const Window *window)
+{
+    return window->isMinimizable() && window->isOnCurrentDesktop() && window->isOnCurrentActivity();
+}
+
+MinimizeAll::MinimizeAll(Workspace *workspace)
+    : m_workspace(workspace)
+{
+    connect(workspace, &Workspace::windowAdded, this, &MinimizeAll::add);
+    connect(workspace, &Workspace::windowRemoved, this, &MinimizeAll::remove);
+    connect(workspace, &Workspace::currentActivityChanged, this, &MinimizeAll::update);
+    connect(VirtualDesktopManager::self(), &VirtualDesktopManager::currentChanged, this, &MinimizeAll::update);
+}
+
+bool MinimizeAll::isActive() const
+{
+    return m_active;
+}
+
+void MinimizeAll::add(Window *window)
+{
+    connect(window, &Window::minimizedChanged, this, &MinimizeAll::update);
+    connect(window, &Window::desktopsChanged, this, &MinimizeAll::update);
+    connect(window, &Window::activitiesChanged, this, &MinimizeAll::update);
+    connect(window, &Window::outputChanged, this, &MinimizeAll::update);
+    update();
+}
+
+void MinimizeAll::remove(Window *window)
+{
+    disconnect(window, nullptr, this, nullptr);
+    m_minimizedWindows.remove(window);
+    update();
+}
+
+void MinimizeAll::update()
+{
+    const bool active = std::ranges::any_of(m_minimizedWindows, isRelevant) && std::ranges::none_of(m_workspace->windows(), [](const Window *window) {
+        return isRelevant(window) && !window->isMinimized();
+    });
+    if (m_active != active) {
+        m_active = active;
+        Q_EMIT activeChanged(active);
+    }
+}
+
+QList<Window *> MinimizeAll::relevantWindows(LogicalOutput *output) const
+{
+    QList<Window *> windows;
+    for (Window *window : m_workspace->windows()) {
+        if (isRelevant(window) && (!output || window->output() == output)) {
+            windows.append(window);
+        }
+    }
+    return windows;
+}
+
+bool MinimizeAll::toggleWindows(QList<Window *> &windows)
+{
+    const bool minimize = std::ranges::any_of(windows, [](const Window *window) {
+        return !window->isMinimized();
+    });
+
+    // Try to preserve the topmost window by sorting windows.
+    std::ranges::sort(windows, [](const Window *a, const Window *b) {
+        if (a->isActive() != b->isActive()) {
+            return b->isActive();
+        }
+        return a->stackingOrder() < b->stackingOrder();
+    });
+
+    for (Window *window : std::as_const(windows)) {
+        const bool wasMinimizedByUs = m_minimizedWindows.remove(window);
+        if (minimize) {
+            if (!window->isMinimized()) {
+                m_minimizedWindows.insert(window);
+                window->setMinimized(true);
+            }
+        } else if (wasMinimizedByUs) {
+            window->setMinimized(false);
+        }
+    }
+
+    update();
+    return minimize;
+}
+
+void MinimizeAll::toggle(LogicalOutput *output)
+{
+    QList<Window *> windows = relevantWindows(output);
+    if (!toggleWindows(windows) && !windows.isEmpty() && windows.last() != m_workspace->activeWindow()) {
+        m_workspace->activateWindow(windows.last());
+    }
+}
+
+void MinimizeAll::toggleOthers(LogicalOutput *output)
+{
+    QList<Window *> windows = relevantWindows(output);
+    windows.removeIf([](const Window *window) {
+        return window->isActive();
+    });
+    toggleWindows(windows);
+}
+
+}
+
+#include "moc_minimizeall.cpp"
