+#include <QList>
+#include <QObject>
+#include <QSet>
+
+namespace KWin
+{
+
+class LogicalOutput;
+class Window;
+class Workspace;
+
+/**
+ * Minimizes all windows on the current virtual desktop and activity, and restores
+ * the windows it minimized when toggled again. The Minimize All script and the
+ * org.kde.KWin D-Bus interface both go through it, so they can undo each other.
+ */
+class MinimizeAll : public QObject
+{
+    Q_OBJECT
+
+public:
+    explicit MinimizeAll(Workspace *workspace);
+
+    /**
+     * Whether toggling restores windows: all windows on the current virtual desktop
+     * and activity are minimized, and some of them were minimized by toggling.
+     */
+    bool isActive() const;
+
+    /**
+     * Minimizes all windows, or restores them if they are all minimized already.
+     * If @p output is set, only the windows on that output are affected.
+     */
+    void toggle(LogicalOutput *output = nullptr);
+
+    /**
+     * Like toggle(), but leaves the active window alone.
+     */
+    void toggleOthers(LogicalOutput *output = nullptr);
+
+Q_SIGNALS:
+    void activeChanged(bool active);
+
+private:
+    void add(Window *window);
+    void remove(Window *window);
+    void update();
+    QList<Window *> relevantWindows(LogicalOutput *output) const;
+    bool toggleWindows(QList<Window *> &windows);
+
+    Workspace *const m_workspace;
+    QSet<Window *> m_minimizedWindows;
+    bool m_active = false;
+};
+
+}
