+
+#include "minimizeall.h"
+
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
+#include <QDBusVariant>
+
+MinimizeAll::MinimizeAll(QObject *parent)
+    : QObject(parent)
+{
+    m_interface = new OrgKdeKWinInterface(QStringLiteral("org.kde.KWin"), QStringLiteral("/KWin"), QDBusConnection::sessionBus(), this);
+    connect(m_interface, &OrgKdeKWinInterface::minimizingAllChanged, this, &MinimizeAll::setMinimizingAll);
+
+    QDBusMessage message =
+        QDBusMessage::createMethodCall(m_interface->service(), m_interface->path(), QStringLiteral("org.freedesktop.DBus.Properties"), QStringLiteral("Get"));
+    message << m_interface->interface() << QStringLiteral("minimizingAll");
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        const QDBusPendingReply<QDBusVariant> reply = *watcher;
+        if (!reply.isError()) {
+            setMinimizingAll(reply.value().variant().toBool());
+        }
+        watcher->deleteLater();
+    });
+}
+
+MinimizeAll::~MinimizeAll() = default;
+
+bool MinimizeAll::minimizingAll() const
+{
+    return m_minimizingAll;
+}
+
+void MinimizeAll::setMinimizingAll(bool minimizingAll)
+{
+    if (m_minimizingAll != minimizingAll) {
+        m_minimizingAll = minimizingAll;
+        Q_EMIT minimizingAllChanged(minimizingAll);
+    }
+}
+
+void MinimizeAll::toggle()
+{
+    m_interface->toggleMinimizeAll();
+}
